const X = size_x, Z = size_z, r = radius, g = Math.min(gap, r), s = seed;
const dx = 1.5 * r, dz = Math.sqrt(3) * r, nx = Math.floor(X / 2 / dx) + 1, nz = Math.floor(Z / 2 / dz) + 1;
const k = (r - g / Math.sqrt(3)) / r;
for (let i = -nx; i <= nx; i++) for (let j = -nz - 1; j <= nz; j++) {
  const x = i * dx, z = j * dz + (Math.abs(i) % 2 ? dz / 2 : 0);
  if (Math.abs(x) > X / 2 || Math.abs(z) > Z / 2) continue;
  const h = Math.max(0.005, height + (rand(i, j, s) - 0.5) * 2 * height_jitter);
  const q = addpoint(0, [x, 0, z]);
  setpointattrib(0, 'scale', q, [r * k, h, r * k]);
  setpointattrib(0, 'tint', q, 0.78 + 0.35 * rand(i, j, s, 2));
}
